if (!pm.environment.get('m3FixtureReady')) {
  if (pm.environment.get('fixtureMode') !== 'runner') {
    const suffix = pm.variables.replaceIn('{{$guid}}');
    pm.environment.set('customerEmail', 'customer-' + suffix + '@example.test');
    pm.environment.set('designerEmail', 'designer-' + suffix + '@example.test');
    pm.environment.set('authPassword', pm.variables.replaceIn('{{$guid}}') + 'Aa1!');
  }
  pm.environment.set('m3FixtureReady', 'true');
}

