{
  "openapi": "3.0.3",
  "info": {
    "title": "MY GARB PHASONABLE Backend",
    "version": "0.6.0",
    "description": "MY GARB backend M1-M5. Cookie authentication, private profiles, immutable request/order originals, participant text conversations, explicit versioned measurement consent and durable owner-only in-app notifications. Standalone MongoDB; no payments, sockets or admin private-data access. M6 adds bounded admin metadata lists and customer/designer suspension with persistent session revocation."
  },
  "servers": [
    {
      "url": "/"
    }
  ],
  "paths": {
    "/api/health/live": {
      "get": {
        "summary": "Process liveness (independent of MongoDB)",
        "description": "No authentication. No request body. Health probes are exempt from rate limiting.",
        "security": [],
        "responses": {
          "200": {
            "description": "Service is alive",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "success",
                    "data"
                  ],
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "enum": [
                        true
                      ]
                    },
                    "data": {
                      "type": "object",
                      "required": [
                        "status"
                      ],
                      "properties": {
                        "status": {
                          "type": "string",
                          "enum": [
                            "alive"
                          ]
                        }
                      }
                    }
                  }
                },
                "example": {
                  "success": true,
                  "data": {
                    "status": "alive"
                  }
                }
              }
            }
          },
          "400": {
            "description": "Malformed JSON",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                },
                "example": {
                  "success": false,
                  "error": {
                    "code": "INVALID_JSON",
                    "message": "Malformed JSON body"
                  }
                }
              }
            }
          },
          "413": {
            "description": "JSON exceeds 16 KB",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                },
                "example": {
                  "success": false,
                  "error": {
                    "code": "BODY_TOO_LARGE",
                    "message": "Request body exceeds limit"
                  }
                }
              }
            }
          },
          "415": {
            "description": "Unsupported body encoding or charset",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                },
                "example": {
                  "success": false,
                  "error": {
                    "code": "UNSUPPORTED_ENCODING",
                    "message": "Unsupported body encoding"
                  }
                }
              }
            }
          },
          "500": {
            "description": "Unexpected error",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                },
                "example": {
                  "success": false,
                  "error": {
                    "code": "INTERNAL_ERROR",
                    "message": "An unexpected error occurred"
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/health/ready": {
      "get": {
        "summary": "Readiness (MongoDB connected)",
        "description": "No authentication. No request body. Health probes are exempt from rate limiting.",
        "security": [],
        "responses": {
          "200": {
            "description": "Service is ready",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "success",
                    "data"
                  ],
                  "properties": {
                    "success": {
                      "type": "boolean",
                      "enum": [
                        true
                      ]
                    },
                    "data": {
                      "type": "object",
                      "required": [
                        "status"
                      ],
                      "properties": {
                        "status": {
                          "type": "string",
                          "enum": [
                            "ready"
                          ]
                        }
                      }
                    }
                  }
                },
                "example": {
                  "success": true,
                  "data": {
                    "status": "ready"
                  }
                }
              }
            }
          },
          "400": {
            "description": "Malformed JSON",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Error"
                },
                "example": {
                  "success": false,
                  "error": {
                    "code": "INVALID_JSON",
                    "message": "Malformed JSON body"
                  }
                }
              }
            }
          },
          "413": {
